window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b4e8a3ef64d14462"]={"versions": [{"id": "FIG-b4e8a3ef64d14462", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC) im Kontext des Moduls EcuM Fixed (<code>AUTOSAR_SWS_ECUStateManagerFixed</code>). Das Diagramm spezifiziert die Konfigurationsstruktur für ECU-State-Manager-Benutzer (<code>EcuMFixedUser</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei ECUC-Klassenelemente und deren Beziehung:</p>\n<ul class=\"fig-list\"><li><code>EcuMFixedUserConfig : EcucParamConfContainerDef</code>: Container-Definition mit den Attributen <code>upperMultiplicity = *</code> und <code>lowerMultiplicity = 1</code>.\n</li><li><code>EcuMFixedUser : EcucIntegerParamDef</code>: Ganzzahliger Konfigurationsparameter mit den Wertegrenzen <code>min = 0</code>, <code>max = 255</code> sowie dem Flag <code>symbolicNameValue = true</code>.\n</li><li>Kompositionsbeziehung: <code>EcuMFixedUserConfig</code> enthält über die Kompositionsrolle <code>+parameter</code> den Parameter <code>EcuMFixedUser</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell zur BSW-Generierungs- und Konfigurationszeit; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für ECUC-Parameter-Generatoren und BSW-Konfigurationstools:</p>\n<ul class=\"fig-list\"><li>Mindestens eine Instanz des Containers <code>EcuMFixedUserConfig</code> ist erforderlich (<code>lowerMultiplicity = 1</code>), beliebig viele sind zulässig (<code>*</code>).\n</li><li>Der Parameter <code>EcuMFixedUser</code> definiert einen 8-Bit-Identifikator (<code>0</code> bis <code>255</code>) für registrierte Fixed-EcuM-Nutzer.\n</li><li>Durch <code>symbolicNameValue = true</code> muss für jede konfigurierte Instanz ein symbolischer Bezeichner (C-Makro/Literal) für den Zugriff auf API-Ebene generiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4976b41e0d70aa17", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC) im Kontext des Moduls EcuM Fixed (<code>AUTOSAR_SWS_ECUStateManagerFixed</code>). Das Diagramm spezifiziert die Konfigurationsstruktur für ECU-State-Manager-Benutzer (<code>EcuMFixedUser</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei ECUC-Klassenelemente und deren Beziehung:</p>\n<ul class=\"fig-list\"><li><code>EcuMFixedUserConfig : EcucParamConfContainerDef</code>: Container-Definition mit den Attributen <code>upperMultiplicity = *</code> und <code>lowerMultiplicity = 1</code>.\n</li><li><code>EcuMFixedUser : EcucIntegerParamDef</code>: Ganzzahliger Konfigurationsparameter mit den Wertegrenzen <code>min = 0</code>, <code>max = 255</code> sowie dem Flag <code>symbolicNameValue = true</code>.\n</li><li>Kompositionsbeziehung: <code>EcuMFixedUserConfig</code> enthält über die Kompositionsrolle <code>+parameter</code> den Parameter <code>EcuMFixedUser</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell zur BSW-Generierungs- und Konfigurationszeit; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für ECUC-Parameter-Generatoren und BSW-Konfigurationstools:</p>\n<ul class=\"fig-list\"><li>Mindestens eine Instanz des Containers <code>EcuMFixedUserConfig</code> ist erforderlich (<code>lowerMultiplicity = 1</code>), beliebig viele sind zulässig (<code>*</code>).\n</li><li>Der Parameter <code>EcuMFixedUser</code> definiert einen 8-Bit-Identifikator (<code>0</code> bis <code>255</code>) für registrierte Fixed-EcuM-Nutzer.\n</li><li>Durch <code>symbolicNameValue = true</code> muss für jede konfigurierte Instanz ein symbolischer Bezeichner (C-Makro/Literal) für den Zugriff auf API-Ebene generiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-af62109137b192c1", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC) im Kontext des Moduls EcuM Fixed (<code>AUTOSAR_SWS_ECUStateManagerFixed</code>). Das Diagramm spezifiziert die Konfigurationsstruktur für ECU-State-Manager-Benutzer (<code>EcuMFixedUser</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei ECUC-Klassenelemente und deren Beziehung:</p>\n<ul class=\"fig-list\"><li><code>EcuMFixedUserConfig : EcucParamConfContainerDef</code>: Container-Definition mit den Attributen <code>upperMultiplicity = *</code> und <code>lowerMultiplicity = 1</code>.\n</li><li><code>EcuMFixedUser : EcucIntegerParamDef</code>: Ganzzahliger Konfigurationsparameter mit den Wertegrenzen <code>min = 0</code>, <code>max = 255</code> sowie dem Flag <code>symbolicNameValue = true</code>.\n</li><li>Kompositionsbeziehung: <code>EcuMFixedUserConfig</code> enthält über die Kompositionsrolle <code>+parameter</code> den Parameter <code>EcuMFixedUser</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell zur BSW-Generierungs- und Konfigurationszeit; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für ECUC-Parameter-Generatoren und BSW-Konfigurationstools:</p>\n<ul class=\"fig-list\"><li>Mindestens eine Instanz des Containers <code>EcuMFixedUserConfig</code> ist erforderlich (<code>lowerMultiplicity = 1</code>), beliebig viele sind zulässig (<code>*</code>).\n</li><li>Der Parameter <code>EcuMFixedUser</code> definiert einen 8-Bit-Identifikator (<code>0</code> bis <code>255</code>) für registrierte Fixed-EcuM-Nutzer.\n</li><li>Durch <code>symbolicNameValue = true</code> muss für jede konfigurierte Instanz ein symbolischer Bezeichner (C-Makro/Literal) für den Zugriff auf API-Ebene generiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e01bccbe8d8c891e", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC) im Kontext des Moduls EcuM Fixed (<code>AUTOSAR_SWS_ECUStateManagerFixed</code>). Das Diagramm spezifiziert die Konfigurationsstruktur für ECU-State-Manager-Benutzer (<code>EcuMFixedUser</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei ECUC-Klassenelemente und deren Beziehung:</p>\n<ul class=\"fig-list\"><li><code>EcuMFixedUserConfig : EcucParamConfContainerDef</code>: Container-Definition mit den Multiplizitätsattributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = *</code>.\n</li><li><code>EcuMFixedUser : EcucIntegerParamDef</code>: Ganzzahliger Konfigurationsparameter mit <code>min = 0</code>, <code>max = 255</code>, den Multiplizitätsattributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code> sowie dem Flag <code>symbolicNameValue = true</code>.\n</li><li>Kompositionsbeziehung: <code>EcuMFixedUserConfig</code> enthält über die Kompositionsrolle <code>+parameter</code> den optionalen Parameter <code>EcuMFixedUser</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell zur BSW-Generierungs- und Konfigurationszeit; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für ECUC-Parameter-Generatoren und BSW-Konfigurationstools:</p>\n<ul class=\"fig-list\"><li>Die Konfiguration des Containers <code>EcuMFixedUserConfig</code> ist optional (<code>lowerMultiplicity = 0</code>), beliebig viele Instanzen sind zulässig (<code>*</code>).\n</li><li>Der Parameter <code>EcuMFixedUser</code> ist innerhalb des Containers optional (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) und repräsentiert einen 8-Bit-Identifikator (<code>0</code> bis <code>255</code>).\n</li><li>Durch <code>symbolicNameValue = true</code> muss bei Vorhandensein eines Parameters ein symbolischer Bezeichner (C-Makro/Literal) für die EcuM-Benutzer-ID generiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b4e8a3ef64d14462", "to": "FIG-4976b41e0d70aa17", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4976b41e0d70aa17", "to": "FIG-af62109137b192c1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-af62109137b192c1", "to": "FIG-e01bccbe8d8c891e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>EcuMFixedUserConfig</code>: Multiplizität von <code>lowerMultiplicity = 1</code> auf <code>lowerMultiplicity = 0</code> geändert (Reihenfolge <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).\n</li><li><code>EcuMFixedUser</code>: Multiplizitätsattribute <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code> ergänzt.\n</li></ul>"}]};
